#include "rmw/bar/Source.hpp"

#include "rmw/bar/Geometry.hpp"

#include <algorithm>
#include <array>
#include <format>

namespace rmw::bar
{
namespace
{

constexpr std::string_view kRootHeader = R"(
// ---- generated by rmw-bar from the rice's zones -------------------------------------------------
export component Bar inherits Window {
    // rmw-bar draws translucent frames twice, over black and over white (see Surface).
    in property <brush> bar-matte: #000000;
    background: root.bar-matte;
    in property <brush> bar-background: #000000;
    in property <length> bar-radius: 0px;
    in property <color> bar-foreground: #ffffff;
)";

} // namespace

GeneratedBar generateBarSource(const domain::BarConfig& bar, std::span<const WidgetKind> kinds,
                               std::string_view widgetSources)
{
    GeneratedBar generated;
    const bool horizontal = isHorizontal(bar.position);
    std::string declarations;
    std::array<std::string, 3> zones;
    std::size_t next = 0;

    const std::array<const std::vector<domain::BarItem>*, 3> items = {&bar.left, &bar.center, &bar.right};
    for (std::size_t zone = 0; zone < items.size(); ++zone)
    {
        for (const auto& item : *items[zone])
        {
            const auto kind = std::ranges::find(kinds, item.id, &WidgetKind::id);
            if (kind == kinds.end())
            {
                generated.unknown.push_back(item.id);
                continue;
            }
            const std::string prefix = std::format("w{}", next++);
            std::string bindings;
            for (const auto& property : kind->properties)
            {
                declarations +=
                    std::format("    in property <{}> {}-{};\n", property.type, prefix, property.name);
                bindings += std::format(" {0}: root.{1}-{0};", property.name, prefix);
            }
            for (const std::string_view callback : kind->callbacks)
            {
                // "clicked" or "activate(int)": the arguments are passed through as they come.
                const auto open = callback.find('(');
                const std::string_view name = callback.substr(0, open);
                const std::string_view types = open == std::string_view::npos
                                                   ? std::string_view{}
                                                   : callback.substr(open + 1, callback.size() - open - 2);
                std::string arguments;
                for (std::size_t i = 0, count = types.empty() ? 0 : std::ranges::count(types, ',') + 1;
                     i < count; ++i)
                {
                    arguments += std::format("{}a{}", i == 0 ? "" : ", ", i);
                }
                declarations += std::format("    callback {}-{}({});\n", prefix, name, types);
                bindings += arguments.empty() ? std::format(" {0} => {{ root.{1}-{0}(); }}", name, prefix)
                                              : std::format(" {0}({2}) => {{ root.{1}-{0}({2}); }}", name,
                                                            prefix, arguments);
            }
            const std::string_view component =
                !horizontal && !kind->verticalComponent.empty() ? kind->verticalComponent : kind->component;
            zones[zone] +=
                std::format("            {} {{ foreground: root.bar-foreground; vertical: {};{} }}\n",
                            component, horizontal ? "false" : "true", bindings);
            generated.slots.push_back({prefix, &item, &*kind});
        }
    }

    // Three zones on one surface: start, center and end, like Waybar. The center one stays
    // centered whatever the other two hold.
    const std::string_view layout = horizontal ? "HorizontalLayout" : "VerticalLayout";
    const std::string_view along = horizontal ? "width" : "height";
    const std::string_view across = horizontal ? "height" : "width";
    const std::string_view axis = horizontal ? "x" : "y";
    const std::string_view startPadding = horizontal ? "padding-left" : "padding-top";
    const std::string_view endPadding = horizontal ? "padding-right" : "padding-bottom";
    const std::array<std::string, 3> placement = {
        std::format("{}: 0px; {}: 6px;", axis, startPadding),
        std::format("{0}: (parent.{1} - self.{1}) / 2;", axis, along),
        std::format("{0}: parent.{1} - self.{1}; {2}: 6px;", axis, along, endPadding),
    };

    std::string root(kRootHeader);
    root += declarations;
    root += "    Rectangle {\n"
            "        background: root.bar-background;\n"
            "        border-radius: root.bar-radius;\n";
    for (std::size_t zone = 0; zone < zones.size(); ++zone)
    {
        root += std::format("        {} {{\n"
                            "            {}: self.preferred-{}; {}: parent.{}; {}\n"
                            "            spacing: 4px;\n"
                            "{}"
                            "        }}\n",
                            layout, along, along, across, across, placement[zone], zones[zone]);
    }
    root += "    }\n}\n";

    generated.source.reserve(widgetSources.size() + root.size() + 1);
    generated.source.append(widgetSources);
    generated.source += '\n';
    generated.source += root;
    return generated;
}

} // namespace rmw::bar
